
/* 深色制图风格画布，与状态栏同一色板：
   画布最深、路网亮一档、建筑中灰；绿地/水系用低饱和衍生色保证易读；粉紫 accent 点睛 */
$画布: var(--c-bg);
$路描边: var(--c-border);
$路填充: #34344a;
$建筑填充: #2b2b3c;
$建筑描边: var(--c-border);
$绿地: #22301f;
$绿地描边: #33452f;
$湖面: #1a2b3d;
$墨色: var(--c-text);
$次级墨: var(--c-text-dim);

.map-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 100%;
}

.toolbar {
  display: flex;
  justify-content: flex-end;
}

.buttons {
  display: flex;
  gap: 6px;

  button {
    font: inherit;
    font-size: 12px;
    padding: 3px 10px;
    color: var(--c-text-dim);
    background: var(--c-surface-2);
    border: 1px solid var(--c-border);
    border-radius: 5px;
    cursor: pointer;
    transition: color 0.15s, border-color 0.15s;

    &:hover {
      color: var(--c-accent);
      border-color: var(--c-accent);
    }
  }
}

.map-box {
  border: 1px solid var(--c-border);
  border-radius: 6px;
  overflow: hidden;
}

.map {
  display: block;
  width: 100%;
  max-width: 640px;
  margin: 0 auto;
  aspect-ratio: 1000 / 760;
  background: $画布;
  touch-action: none;
  user-select: none;
  cursor: grab;

  &:active {
    cursor: grabbing;
  }
}

.canvas-bg {
  fill: $画布;
}

.zone {
  stroke: #26262e;
  stroke-width: 1;
}

.river {
  fill: #1a2b3d;
  stroke: #2e4560;
  stroke-width: 1.5;
}

.flower {
  circle {
    fill: #262433;
    stroke: var(--c-border);
    stroke-width: 1.5;
  }

  .bloom {
    fill: #6b4258;
    stroke: none;
  }
}

.tree {
  .trunk {
    stroke: #3a3a4e;
    stroke-width: 1.5;
  }

  .canopy {
    fill: #2c4030;
    stroke: none;

    &.side {
      fill: #253828;
    }
  }
}

.park {
  fill: $绿地;
  stroke: $绿地描边;
  stroke-width: 1.5;
}

.lake {
  fill: $湖面;
  stroke: none;
}

.playground {
  fill: none;
  stroke: $绿地描边;
  stroke-width: 2;
}

.park-mini {
  fill: $绿地;
  stroke: $绿地描边;
  stroke-width: 1;
  opacity: 0.9;
}

.estate {
  fill: #232233;
  stroke: $路描边;
  stroke-width: 1;
  stroke-dasharray: 5 4;
}

.estate-label {
  fill: $次级墨;
  font-weight: 600;
  paint-order: stroke;
  stroke: $画布;
  stroke-width: 3;
  pointer-events: none;
}

.building {
  fill: $建筑填充;
  stroke: $建筑描边;
  stroke-width: 1;
}

.road-casing {
  fill: none;
  stroke: $路描边;
  stroke-linecap: butt;
  stroke-linejoin: round;

  &.干道 {
    stroke-width: 13;
  }

  &.次干道 {
    stroke-width: 8.5;
  }
}

.road-fill {
  fill: none;
  stroke: $路填充;
  stroke-linecap: butt;
  stroke-linejoin: round;

  &.干道 {
    stroke-width: 9;
  }

  &.次干道 {
    stroke-width: 5;
  }
}

.road-minor {
  fill: none;
  stroke: $路描边;
  stroke-width: 2;
  opacity: 0.55;
  stroke-linecap: round;
}

.road-label {
  fill: $次级墨;
  font-weight: 600;
  paint-order: stroke;
  stroke: $路填充;
  stroke-width: 3;
  pointer-events: none;
}

.metro {
  fill: none;
  stroke: var(--c-accent-2);
  stroke-width: 4.5;
  stroke-linecap: round;
  stroke-dasharray: 12 9;
  opacity: 0.75;
  pointer-events: none;
}

.district-label {
  fill: $次级墨;
  opacity: 0.85;
  font-weight: 600;
  letter-spacing: 0.2em;
  pointer-events: none;
}

.street-casing {
  fill: none;
  stroke: $路描边;
  stroke-width: 6.5;
  stroke-linecap: butt;
  stroke-linejoin: round;
}

.street-fill {
  fill: none;
  stroke: $路填充;
  stroke-width: 3.5;
  stroke-linecap: butt;
  stroke-linejoin: round;
  pointer-events: none;
  transition: stroke 0.15s, width 0.15s;

  &.current,
  &.selected {
    stroke: var(--c-accent);
    stroke-width: 4.5;
  }
}

.street-hit {
  fill: none;
  stroke: transparent;
  stroke-width: 14;
  stroke-linecap: round;
  cursor: pointer;
}

.parkpath-hit {
  fill: none;
  stroke: transparent;
  stroke-width: 12;
  cursor: pointer;
}

.parkpath {
  fill: none;
  stroke: #4a6a55;
  stroke-width: 3;
  stroke-linecap: round;
  opacity: 0.8;
  pointer-events: none;
  transition: opacity 0.15s, stroke 0.15s;

  &.滨水 {
    stroke: #2e4560;
    stroke-width: 3.5;
  }

  &.铁轨 {
    stroke: #3a3a4e;
    stroke-width: 4;
  }

  &.current,
  &.selected {
    opacity: 1;
    stroke: var(--c-accent);
  }
}

.track-dash {
  fill: none;
  stroke: #4f7a63;
  stroke-width: 1.4;
  stroke-dasharray: 6 7;
  pointer-events: none;
}

.rail-ties {
  fill: none;
  stroke: #5a627a;
  stroke-width: 2;
  stroke-dasharray: 2 6;
  pointer-events: none;
}

.node {
  cursor: pointer;

  .hit {
    fill: transparent;
  }

  .poi {
    fill: var(--c-surface-2);
    stroke: $墨色;
    stroke-width: 2;
    transition: stroke 0.15s;

    &.selected {
      stroke: var(--c-accent);
      stroke-width: 3;
    }
  }

  .poi-dot {
    fill: $墨色;
    pointer-events: none;
  }

  &:hover .poi {
    stroke: var(--c-accent);
  }

  &:hover .poi-dot {
    fill: var(--c-accent);
  }

  .pin-body {
    fill: var(--c-accent);
    stroke: var(--c-bg);
    stroke-width: 1.5;
    filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.5));
  }

  .pin-hole {
    fill: var(--c-text);
  }

  .node-label {
    fill: $墨色;
    font-weight: 600;
    paint-order: stroke;
    stroke: $画布;
    stroke-width: 3.5;
    pointer-events: none;

    &.current {
      fill: var(--c-accent);
    }
  }
}

.tooltip {
  pointer-events: none;

  rect {
    fill: rgba(32, 32, 44, 0.97);
    stroke: $墨色;
    stroke-width: 1.2;
  }

  .tip-title {
    fill: $墨色;
    font-weight: 700;
  }

  .tip-line {
    fill: $次级墨;
  }
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 10px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;

  .detail-head {
    display: flex;
    align-items: baseline;
    gap: 8px;

    .name {
      color: var(--c-text);
      font-weight: 600;
      font-size: 13px;
    }

    .tag {
      color: var(--c-text-dim);
      font-size: 11px;
    }
  }

  .meta {
    display: flex;
    gap: 14px;
    color: var(--c-accent);
    font-size: 12px;
  }

  .desc {
    color: var(--c-text-dim);
    font-size: 12px;
    line-height: 1.6;
  }
}

.location-text {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-text);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-accent);
  flex-shrink: 0;
}
