
.outfit-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 100%;
}

.block {
  border: 1px solid var(--c-border);
  border-radius: 6px;
  background: var(--c-surface);
  overflow: hidden;
}

.block:last-child {
  flex: 1;
}

.carry-block {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.block-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.block-title {
  padding: 6px 10px;
  font-size: 12px;
  color: var(--c-text-dim);
  background: var(--c-surface-2);
  border-bottom: 1px solid var(--c-border);
}

.row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 5px 10px;
  border-bottom: 1px solid var(--c-border);
}

.row:last-child {
  border-bottom: none;
}

.label {
  color: var(--c-text-dim);
  flex-shrink: 0;
}

.value {
  color: var(--c-text);
  text-align: right;
  word-break: break-all;
}

.value.dim {
  color: var(--c-text-dim);
  text-align: left;
}
